local config = {
  ui_story_30090401_1_dialog_content = "I stare at the box in front of me.",
  ui_story_30090401_X1_dialog_content = "The clean and sturdy hard leather white box looks well-maintained.",
  ui_story_30090401_2_dialog_content = "The metal handle is covered in fine leather.",
  ui_story_30090401_3_dialog_content = "But it's just a box after all, and I have been staring at it for a long time.",
  ui_story_30090401_4_dialog_content = "Time gradually passes, and the current situation feels absurd.",
  ui_story_30090401_5_dialog_content = "This all happened because Faust asked me for a favor.",
  ui_story_30090401_6_dialog_content = "So you want me to look after a <color=#FFB400>white suitcase</color>, your suitcase.",
  ui_story_30090401_8_dialog_content = "Actually, Colossus has a place just for storing things, maybe you can put it there.",
  ui_story_30090401_9_dialog_content = "This suitcase is different. You have to handle it with extra care.",
  ui_story_30090401_10_dialog_content = "When I needed help, I used to ask my friends from the Association—",
  ui_story_30090401_11_dialog_content = "But Lady Victoria is busy, and I don't know where Nails and Pact are.",
  ui_story_30090401_12_dialog_content = "I realized only you could help me.",
  ui_story_30090401_13_dialog_content = "Where are you going?",
  ui_story_30090401_14_dialog_content = "To repay the believers.",
  ui_story_30090401_15_dialog_content = "Ah—",
  ui_story_30090401_16_dialog_content = "I'm embarrassed to say this, but I have a fan club.",
  ui_story_30090401_17_option_content = "Hold on a minute. I've never heard of this.",
  ui_story_30090401_18_dialog_content = "Speaking of my fan club—",
  ui_story_30090401_19_dialog_content = "All of my fans are cute and caring girls, as well as devout believers of the Truth.",
  ui_story_30090401_20_dialog_content = "Anyone would be grateful to receive so much love, and I'm no exception.",
  ui_story_30090401_21_dialog_content = "*Look at Faust with shock*",
  ui_story_30090401_22_dialog_content = "Of course, I also felt it when my dear PlayerName cared for me. I'll repay you when the time is right.",
  ui_story_30090401_23_option_content = "Wow, I would love to have my own fan club...",
  ui_story_30090401_24_dialog_content = "I've been your believer and fan from the beginning.",
  ui_story_30090401_25_dialog_content = "I know you are just trying to make me feel better, but it works.",
  ui_story_30090401_26_dialog_content = "I'm not lying. I never lie.",
  ui_story_30090401_27_dialog_content = "Anyway, I organize tea parties for my believers from time to time. I've made them some nice little trinkets this time to express my gratitude.",
  ui_story_30090401_28_dialog_content = "There's a Bloody Bible version, a Nails version, a Hunting Stone version...",
  ui_story_30090401_29_dialog_content = "And a white suitcase version of course—I even made two versions—black and white.",
  ui_story_30090401_30_dialog_content = "But...",
  ui_story_30090401_31_dialog_content = "My cute little box didn't like the mini versions and ate all the ones I made.",
  ui_story_30090401_32_dialog_content = "Wait... ate? This box can eat? Isn't it just a regular box?",
  ui_story_30090401_33_dialog_content = "No, the white suitcase is alive.",
  ui_story_30090401_34_dialog_content = "You mean, the white suitcase is a living being?",
  ui_story_30090401_35_dialog_content = "Yes and no. It does have its tempers like a living being. If you stuff in it a lot of gifts, it's bound to get angry.",
  ui_story_30090401_36_dialog_content = "And it's not that approachable...",
  ui_story_30090401_37_dialog_content = "This is also why I can't bring it to my fan club. I have to bring a substitute instead.",
  ui_story_30090401_38_dialog_content = "A living box, sounds bizarre.",
  ui_story_30090401_39_dialog_content = "Oh no, it's almost time!",
  ui_story_30090401_40_dialog_content = "Anyway, I'm counting on you, dear PlayerName!",
  ui_story_30090401_41_dialog_content = "This is a list of tips for taking care of Wispy. Please use it.",
  ui_story_30090401_42_dialog_content = "If you don't complete them, terrible things will happen.",
  ui_story_30090401_43_dialog_content = "What terrible things?",
  ui_story_30090401_44_dialog_content = "Something like the Colossus being eaten.",
  ui_story_30090401_45_dialog_content = "What? Hey, wait! I don't understand!!!",
  ui_story_30090401_46_dialog_content = "So that brings us to now.",
  ui_story_30090401_47_dialog_content = "The Colossus being eaten... That must be a joke, it's ridiculous.",
  ui_story_30090401_48_dialog_content = "\"... I never lie.\"",
  ui_story_30090401_49_dialog_content = "But I can't just ignore what these people say...",
  ui_story_30090401_50_dialog_content = "*Look down at the list*",
  ui_story_30090401_51_dialog_content = "*Opens a little slit*",
  ui_story_30090401_52_dialog_content = "<color=#FFFFFF>Wispy's Guide and Tips</color>",
  ui_story_30090401_53_dialog_content = "<size=37><color=#FFFFFF>1. Place Wispy in a place that's not too cold and not too hot.</color></size>",
  ui_story_30090401_A1_dialog_content = "<size=37><color=#FFFFFF>Try not to make its paint come off or the handle rust.</color></size>",
  ui_story_30090401_X53_dialog_content = "<size=37><color=#FFFFFF>2. Clean daily. Use a napkin to lightly clean the surface of the suitcase.</color></size>",
  ui_story_30090401_A2_dialog_content = "<size=37><color=#FFFFFF>If the suitcase shakes violently, wait until it calms down.</color></size>",
  ui_story_30090401_X54_dialog_content = "<size=37><color=#FFFFFF>3. Don't open the suitcase by force. If you must open it...</color></size>",
  ui_story_30090401_A3_dialog_content = "<size=37><color=#FFFFFF>Stare at it and wait for it to open on its own.</color></size>",
  ui_story_30090401_X55_dialog_content = "<size=37><color=#FFFFFF>...</color></size>",
  ui_story_30090401_54_dialog_content = "<size=37><color=#FFFFFF>10. Wispy needs to be fed every day. The feeding time is at noon.</color></size>",
  ui_story_30090401_A4_dialog_content = "<size=37><color=#FFFFFF>The suitcase must be open for Wispy to be fed. Check note #3 for how to open the box.</color></size>",
  ui_story_30090401_X57_dialog_content = "<size=37><color=#FFFFFF>If you miss the feeding time, something terrible will happen.</color></size>",
  ui_story_30090401_A5_dialog_content = "<size=37><color=#FFFFFF>You don't want to find out what it is.</color></size>",
  ui_story_30090401_55_dialog_content = "*Closes*",
  ui_story_30090401_56_dialog_content = "*Raise head* I keep feeling like it looked at me...",
  ui_story_30090401_57_dialog_content = "Daily cleaning and disease prevention are completed. I can tick those boxes.",
  ui_story_30090401_58_dialog_content = "This isn't an easy task at all. Just the cleaning tired me out.",
  ui_story_30090401_59_dialog_content = "As if equipped with a motor, this box shakes violently whenever touched.",
  ui_story_30090401_60_dialog_content = "I wonder what's in it?",
  ui_story_30090401_61_dialog_content = "There's one thing left on the list—feeding.",
  ui_story_30090401_62_dialog_content = "According to the list, Wispy eats—",
  ui_story_30090401_63_dialog_content = "Nightmares, sad memories, dying curses, hopeless faith, and ice water.",
  ui_story_30090401_64_dialog_content = "But where am I going to find all these strange things? So, I only managed to prepare some ice water.",
  ui_story_30090401_65_dialog_content = "But then there's another predicament. According to the list, I should stare at it and wait for it to open on its own.",
  ui_story_30090401_66_dialog_content = "But it's been an hour, and my eyes are strained. It doesn't seem like it's going to open.",
  ui_story_30090401_67_dialog_content = "...",
  ui_story_30090401_68_dialog_content = "...",
  ui_story_30090401_69_option_content = "Open it by force",
  ui_story_30090401_70_dialog_content = "Looks like I have to use force.",
  ui_story_30090401_71_dialog_content = "*Try to open box*",
  ui_story_30090401_72_dialog_content = "<color=#e8d9bb>The suitcase opens a little.</color>",
  ui_story_30090401_73_dialog_content = "I think it's working! Wait...",
  ui_story_30090401_74_dialog_content = "My finger got caught, it hurts!!!!",
  ui_story_30090401_75_dialog_content = "This is not going to work.",
  ui_story_30090401_76_option_content = "Keep staring",
  ui_story_30090401_77_dialog_content = "*Stare*",
  ui_story_30090401_78_dialog_content = "*Keep staring*",
  ui_story_30090401_79_dialog_content = "...",
  ui_story_30090401_X79_dialog_content = "My eyes are so dry I feel like they're going to fall out...",
  ui_story_30090401_80_dialog_content = "I give up.",
  ui_story_30090401_81_dialog_content = "I should go do something else.",
  ui_story_30090401_82_dialog_content = "*Opens sneakily*",
  ui_story_30090401_83_dialog_content = "*Closes*",
  ui_story_30090401_84_dialog_content = "Was I imagining it? Whatever, I'm leaving.",
  ui_story_30090401_85_dialog_content = "*Opens up a bit more*",
  ui_story_30090401_86_dialog_content = "...",
  ui_story_30090401_87_dialog_content = "Hah, caught you!!",
  ui_story_30090401_88_dialog_content = "I spent the whole hour staring at you and you didn't open, but once I turned around and left, you opened on your own. You're so hard to deal with!",
  ui_story_30090401_89_dialog_content = "Hurry up and drink the ice water, then let me see what's... inside you...",
  ui_story_30090401_90_dialog_content = "Woah! What is this?!",
  ui_story_30090401_91_dialog_content = "<color=#e8d9bb>Frightened, the suitcase closes itself and shakes violently for some time before calming down.</color>",
  ui_story_30090401_92_dialog_content = "Red wisps, and I think I saw a very big and bright pair of eyes...",
  ui_story_30090401_93_dialog_content = "Is Faust keeping an octopus in there?",
  ui_story_30090401_94_dialog_content = "Oh no, it's not opening again, how am I going to feed it...",
  ui_story_30090401_95_dialog_content = "Oh yeah! The caretaking list!",
  ui_story_30090401_96_dialog_content = "\"... If Wispy is being absolutely stubborn, try soothing it by praising it.\"",
  ui_story_30090401_97_dialog_content = "A box that needs soothing... ridiculous...",
  ui_story_30090401_98_dialog_content = "*Shakes violently again*",
  ui_story_30090401_99_dialog_content = "Sorry, sorry.",
  ui_story_30090401_100_dialog_content = "Ahem, cute little box, I got you this extremely delicious, extremely fresh ice water!",
  ui_story_30090401_101_dialog_content = "Please open up.",
  ui_story_30090401_102_dialog_content = "*Stays still*",
  ui_story_30090401_103_dialog_content = "Little box? Cute little box?",
  ui_story_30090401_104_dialog_content = "Ah, what am I to do?",
  ui_story_30090401_105_dialog_content = "I can't even take care of a box, how am I going to face Faust when he comes back?",
  ui_story_30090401_106_dialog_content = "I'm so sad, I'm going to cry.",
  ui_story_30090401_107_dialog_content = "*Opens slowly and reaches out wisps*",
  ui_story_30090401_108_dialog_content = "Eh...",
  ui_story_30090401_109_dialog_content = "*Caresses with wisps*",
  ui_story_30090401_110_dialog_content = "Are you soothing me? Thanks...",
  ui_story_30090401_111_dialog_content = "Why are you crying too? Who knew a strange box being could empathize?",
  ui_story_30090401_112_dialog_content = "*Shakes wisps slightly, as if agreeing*",
  ui_story_30090401_113_dialog_content = "I don't know why but I feel your warmth.",
  ui_story_30090401_114_dialog_content = "Thank you Wispy, you shouldn't feel sad either.",
  ui_story_30090401_115_dialog_content = "It's not sad.",
  ui_story_30090401_116_dialog_content = "Oh? Faust, you are back?",
  ui_story_30090401_117_dialog_content = "Yes, it took a while.",
  ui_story_30090401_118_dialog_content = "I had to treat my cute believers with utmost sincerity.",
  ui_story_30090401_X118_dialog_content = "Though I used a fake box, nobody knew.",
  ui_story_30090401_119_dialog_content = "I took the trinkets out of the box and gave them out. All of the believers cried tears of joy.",
  ui_story_30090401_120_dialog_content = "I could do that all thanks to you for taking care of Wispy for me.",
  ui_story_30090401_121_dialog_content = "Thanks, but I still feel sorry for making Wispy cry.",
  ui_story_30090401_122_dialog_content = "No, those were not tears.",
  ui_story_30090401_123_dialog_content = "<color=#FFB400>Sad memories are Wispy's favorite food</color>. It was just hungry.",
  ui_story_30090401_124_dialog_content = "So... It saw my sadness and despair and drooled?",
  ui_story_30090401_125_dialog_content = "Unfortunately, I'm afraid so.",
  ui_story_30090401_126_dialog_content = "*Moves wisps happily*",
  ui_story_30090401_127_dialog_content = "Oh, I see.",
  ui_story_30090401_128_dialog_content = "<size=45>Ehh—</size>",
  ui_story_30090401_129_dialog_content = "<color=#e8d9bb>Wispy is like a cat, it has a personality. Be gentle with it.</color>",
  ui_story_30090601_1_dialog_content = "Twin Pavilions Bay market... This place feels like it's always all hustle and bustle, day and night.",
  ui_story_30090601_2_dialog_content = "Huh? That person in front looks like...",
  ui_story_30090601_3_dialog_content = "It's not every day we get such an 'andsome young man perusing our wares. Tell ya what, I'll give ya a twenny-percent discount on any of these books that take yer fancy.",
  ui_story_30090601_4_dialog_content = "Thanks for the kind gesture, ma'am.",
  ui_story_30090601_5_dialog_content = "If these ancient books help to shed some light on the truth, I'd be forever indebted to your kindness.",
  ui_story_30090601_6_dialog_content = "You're a polite one, aren't ya! Heheh... It's been a while since anyone's called me \"ma'am.\"",
  ui_story_30090601_7_dialog_content = "By the way, I've got a fair few incomplete old books in me store. Would ya be interested in 'avin a look, young man?",
  ui_story_30090601_8_dialog_content = "Of course, I'd love to take a look, if that's alright with you.",
  ui_story_30090601_9_dialog_content = "At first, I wasn't quite sure from that outfit, but that demeanor and that manner of speaking...",
  ui_story_30090601_10_dialog_content = "Faust, it's really you.",
  ui_story_30090601_11_dialog_content = "PlayerName? I didn't think I'd run into you here. What a pleasant surprise.",
  ui_story_30090601_12_dialog_content = "What are you doing here? And what's with all the books?",
  ui_story_30090601_13_dialog_content = "I've been studying the ancient culture of Longzhou recently.",
  ui_story_30090601_14_dialog_content = "And I find that the best way to study a culture is to immerse oneself in it.",
  ui_story_30090601_15_dialog_content = "In order to fully understand the significance of a culture's clothing, food, and mannerisms, one must personally experience them.",
  ui_story_30090601_16_dialog_content = "So recently, I've been staying here in Twin Pavilions Bay, gathering together a number of ancient books and cultural relics of Longzhou.",
  ui_story_30090601_17_dialog_content = "<color=#e8d9bb>Bang!</color>",
  ui_story_30090601_18_dialog_content = "Here—these are all of our old mishmashed texts.",
  ui_story_30090601_19_dialog_content = "Anyway, no one's been wantin' to take 'em off me hands after all this time, so if you want 'em, just take 'em all, free of charge.",
  ui_story_30090601_20_dialog_content = "<size=45>There are so many of them!</size>",
  ui_story_30090601_21_dialog_content = "But they really are all in bits and pieces. Not even a single page of these books is intact. Can you still even read them...?",
  ui_story_30090601_22_dialog_content = "I'll never forget your generosity, ma'am.",
  ui_story_30090601_23_dialog_content = "Now, please allow me to place these ancient books in my suitcase.",
  ui_story_30090601_24_dialog_content = "Hang on! Don't do something so dangerous in front of all these people.",
  ui_story_30090601_25_dialog_content = "Where are you staying now? Let me help carry them.",
  ui_story_30090601_26_dialog_content = "Certainly. Thank you very much.",
  ui_story_30090601_27_dialog_content = "Wow... You've got books and all kinds of stuff lying all over the place here. You really don't mess around when it comes to studying, huh?",
  ui_story_30090601_28_dialog_content = "Well, Longzhou has a very long history, and is a vast territory rich in resources.",
  ui_story_30090601_29_dialog_content = "Exploring the origins of such matters is not something one can accomplish overnight.",
  ui_story_30090601_30_dialog_content = "The ancient script of Longzhou is a subject that requires painstaking study in itself.",
  ui_story_30090601_31_dialog_content = "The formation of characters involves pictography, ideograms, association, pictophonetic...",
  ui_story_30090601_32_dialog_content = "Words that once expressed a certain meaning may have evolved into a completely different form in written texts penned ten or a hundred years later.",
  ui_story_30090601_33_dialog_content = "Take these basic ancient texts I read recently, for instance.",
  ui_story_30090601_34_dialog_content = "This character here originally held multiple meanings.",
  ui_story_30090601_35_dialog_content = "But in later texts, it was modified with different radicals.",
  ui_story_30090601_36_dialog_content = "By adding these radical components, the original character developed a range of new meanings...",
  ui_story_30090601_37_dialog_content = "Radicals?",
  ui_story_30090601_38_dialog_content = "Let me write some out for you to see.",
  ui_story_30090601_39_dialog_content = "(He's even got all the calligraphy brushes and special paper ready. I guess he was serious when he said he was immersing himself in the culture.)",
  ui_story_30090601_40_dialog_content = "(And... he's actually pretty good at it!)",
  ui_story_30090601_41_dialog_content = "Just like this, you can branch off into multiple meanings that were originally represented by a single character.",
  ui_story_30090601_42_dialog_content = "Although this system is very intricate, it can also easily lead to confusion.",
  ui_story_30090601_43_dialog_content = "Does this character here mean \"open\"... or does it mean \"establish\"?",
  ui_story_30090601_44_dialog_content = "Hmm? Have you studied this before?",
  ui_story_30090601_45_dialog_content = "No, it's just that I've heard most things in Longzhou are related to the senses somehow.",
  ui_story_30090601_46_dialog_content = "So, this character is placed inside of the radical that represents a door, so I guess the meaning should be something similar to opening a door... Right?",
  ui_story_30090601_47_dialog_content = "And this one contains that little part that indicates movement... so might it be related to the idea of... \"evasion\"?",
  ui_story_30090601_48_dialog_content = "That's precisely correct.",
  ui_story_30090601_49_dialog_content = "I must say, you display an exceptional level of natural talent for this!",
  ui_story_30090601_50_dialog_content = "Come on, I don't know that much about these characters.",
  ui_story_30090601_51_dialog_content = "It's probably just because I've made many friends from Longzhou recently and picked up a few interesting things from them without realizing it.",
  ui_story_30090601_52_dialog_content = "That's just one of your many superpowers.",
  ui_story_30090601_53_dialog_content = "I wonder, could I possibly use your social connections at some point in the future to carry out some on-site fieldwork in Longzhou?",
  ui_story_30090601_54_dialog_content = "Perhaps there are also people on that great continent interested in learning of our wealth of knowledge and many truths.",
  ui_story_30090601_55_dialog_content = "... I knew it.",
  ui_story_30090601_56_dialog_content = "I guess they might be able to see it as simply sharing information and promoting communication between our two continents... It should be fine.",
  ui_story_30090601_57_dialog_content = "Then let me thank you in advance for your kindness.",
  ui_story_30090601_58_dialog_content = "And as a token of gratitude...",
  ui_story_30090601_59_dialog_content = "You've developed some interest in Longzhou's ancient calligraphy by now, have you not?",
  ui_story_30090601_60_dialog_content = "Would you like me to teach you how to write these characters?",
  ui_story_30090601_61_dialog_content = "<size=45>Huh? Really?</size>But these characters all look so complicated...",
  ui_story_30090601_62_dialog_content = "Only through action can we push open the door of truth.",
  ui_story_30090601_63_dialog_content = "Please—take a seat.",
  ui_story_30090601_64_dialog_content = "I'm all for taking action, but how am I supposed to use this brush? The tip is so soft, I can barely control it...",
  ui_story_30090601_65_dialog_content = "Ah! I've smudged ink all over the place!",
  ui_story_30090601_66_dialog_content = "Don't panic.",
  ui_story_30090601_67_dialog_content = "Such writing should not be rushed or executed carelessly, and there should not be a trace of uncertainty in your heart.",
  ui_story_30090601_68_dialog_content = "Your brush must dot the paper like a stone falling resolutely from a mountain peak, extend horizontally, like clouds stretching on for a thousand miles, and glide vertically, like an ageless vine, climbing for all eternity...",
  ui_story_30090601_69_dialog_content = "Follow the momentum of the brush and you'll find the characters form themselves, naturally.",
  ui_story_30090601_70_dialog_content = "Dot the paper, like a stone falling from a mountain peak.",
  ui_story_30090601_71_dialog_content = "Extend horizontally, like clouds stretching for a thousand miles.",
  ui_story_30090601_72_dialog_content = "Glide vertically, like a vine climbing for eternity...",
  ui_story_30090601_73_dialog_content = "I think I'm getting the hang of this! Producing beautiful strokes really isn't as hard as it seems.",
  ui_story_30090601_74_dialog_content = "But... I still think my characters aren't quite on the same level as yours.",
  ui_story_30090601_75_dialog_content = "It's like these strokes I painted just now don't even constitute a single word.",
  ui_story_30090601_76_dialog_content = "Hmm...",
  ui_story_30090601_77_dialog_content = "What do you believe \"words\" to be, in essence?",
  ui_story_30090601_78_option_content = "I guess I've never really thought about it before.",
  ui_story_30090601_79_dialog_content = "Indeed, the more commonly used something is, the more likely we are to overlook its meaning.",
  ui_story_30090601_80_option_content = "They're truly amazing things.",
  ui_story_30090601_81_dialog_content = "Good answer.",
  ui_story_30090601_82_dialog_content = "Although we're quite accustomed to finding ourselves constantly surrounded by words.",
  ui_story_30090601_83_dialog_content = "In my eyes, their mere existence is a precious miracle to be marveled at daily.",
  ui_story_30090601_84_dialog_content = "You wondered before what the purpose of purchasing these broken old books was.",
  ui_story_30090601_85_dialog_content = "Now, I'll tell you why I bought them.",
  ui_story_30090601_86_dialog_content = "It's because words are sparks of truth.",
  ui_story_30090601_87_dialog_content = "Through words, the knowledge of those who came before us can be preserved and accumulated.",
  ui_story_30090601_88_dialog_content = "Transcending the tides of time, they become a poem that can be recited a thousand years on.",
  ui_story_30090601_89_dialog_content = "Although they're fragments, just as fire is born from mere ashes—",
  ui_story_30090601_90_dialog_content = "These scattered sparks possess the ability to stir up a raging storm with just a little help.",
  ui_story_30090601_91_dialog_content = "Every sentence, every word, every character from the past could potentially be a sign left behind by our predecessors on their journey toward the truth.",
  ui_story_30090601_92_dialog_content = "Of course such a legacy is worth cherishing and exploring.",
  ui_story_30090601_93_dialog_content = "Of course!",
  ui_story_30090601_94_dialog_content = "So when you write these characters, don't focus too much on your brushstrokes.",
  ui_story_30090601_95_dialog_content = "Ask yourself why this character possesses such a shape, and what meaning it could possibly hold.",
  ui_story_30090601_96_dialog_content = "The boldness of \"opening\" and the humility of \"evasion\"... It all lies in your strokes.",
  ui_story_30090601_97_dialog_content = "For these characters, this is the most important thing.",
  ui_story_30090601_98_dialog_content = "I see!",
  ui_story_30090601_99_dialog_content = "Calligraphy is actually a lot like my psychic abilities. It's not all just about what you can see...",
  ui_story_30090601_100_dialog_content = "The very point of its existence is to convey more than can be seen with the eye alone.",
  ui_story_30090601_101_dialog_content = "Now that you also understand this profound truth, I believe you'll be able to write with greater confidence.",
  ui_story_30090601_102_dialog_content = "Yes! Thanks, Faust.",
  ui_story_30090601_103_dialog_content = "You must also seek to understand the importance of words in relation to truth.",
  ui_story_30090601_104_dialog_content = "Right!",
  ui_story_30090601_105_dialog_content = "So, that means you must certainly be willing to join the True Order and seek the ultimate truth as one of our members.",
  ui_story_30090601_106_dialog_content = "Yeah... I don't think so.",
  ui_story_30090601_107_dialog_content = "You almost got me there.",
  ui_story_30090601_108_dialog_content = "Sigh... I thought it might actually work that time. What a shame.",
  ui_story_30090601_109_dialog_content = "It's getting late. Let's end our little study session for today.",
  ui_story_30090601_110_dialog_content = "No way... You didn't ask me over just now to try and get me to join the True Order, right?!",
  ui_story_30090601_111_dialog_content = "Haha... Do you really think I would do such a thing?",
  ui_story_30090601_112_dialog_content = "... Do you not?",
  ui_story_30090601_113_dialog_content = "Regardless of my intentions, it was very pleasant exchanging knowledge on history and culture with you.",
  ui_story_30090601_114_dialog_content = "And just take a look at the marvelous calligraphy you produced here today.",
  ui_story_30090601_115_dialog_content = "Seeing your progress to this level in such a short period of time gives me such tremendous satisfaction as a teacher.",
  ui_story_30090601_116_dialog_content = "Thank you for allowing me to enjoy such a fulfilling afternoon.",
  ui_story_30090601_117_dialog_content = "Erm... I should be thanking you for being so patient with me. I really learned a lot today.",
  ui_story_30090601_118_dialog_content = "Well then, if you are truly grateful, could I possibly make a small request of you?",
  ui_story_30090601_119_dialog_content = "I'm not joining the True Order!",
  ui_story_30090601_120_dialog_content = "Alright... It seems I'll have to go with my second choice.",
  ui_story_30090601_121_dialog_content = "Do I really want to know what this \"second choice\" is...?",
  ui_story_30090601_122_dialog_content = "If I really do go to Longzhou in the future, could you please come with me to appreciate the masterpieces of calligraphy produced by the renowned masters of that distant land?",
  ui_story_30090601_123_dialog_content = "Well, that's something I can do! I'm looking forward to it!",
  ui_story_30090601_124_dialog_content = "Before that, though... do you reckon I could still trouble you to teach me some more calligraphy?",
  ui_story_30090601_125_dialog_content = "You're welcome to drop by whenever you like."
